	public v710200(DBConversionParms parms)
	{
		parms.ServerManager.ExecuteCommand(null, parms.User, parms.DatabaseName, "Update APInvoices Set appInvoiceBalanceBase = (Test.appInvoiceTotalBase - (Test.invpay - Test.credpay + Test.offset + Test.exchangeAmt)), appInvoiceBalanceForeign = (Test.appInvoiceTotalForeign - (Test.invpayForeign - Test.credpayForeign + Test.offsetForeign)) From (select appAPInvoiceID, appInvoiceTotalBase, appInvoiceTotalForeign, appInvoiceBalanceBase, appInvoiceBalanceForeign,  isnull((select sum(apnPaymentAmount + apnDiscountAmount + apnDiscountTaxAmount + apnSecondDiscountTaxAmount + apnAdjustmentAmount + apnTaxAmount + apnSecondTaxAmount + apnExchangeAmount) from APPaymentLines inner join APPaymentHeaders on apnAPPaymentSessionID=aptAPPaymentSessionID and apnAPPaymentHeaderID=aptAPPaymentHeaderID where apnAPInvoiceID=appAPInvoiceID AND APPaymentHeaders.aptPostedToGL = -1 AND apnOverpayment = 0),0) as invpay,  isnull((select sum(apnPaymentAmountForeign + apnDiscountAmountForeign + apnDiscountTaxAmountForeign + apnSecondDisTaxAmtForeign + apnAdjustmentAmountForeign + apnTaxAmountForeign + apnSecondTaxAmountForeign) from APPaymentLines inner join APPaymentHeaders on apnAPPaymentSessionID=aptAPPaymentSessionID and apnAPPaymentHeaderID=aptAPPaymentHeaderID where apnAPInvoiceID=appAPInvoiceID AND APPaymentHeaders.aptPostedToGL = -1 AND apnOverpayment = 0),0) as invpayForeign,  isnull((select sum(apnPaymentAmount) from APPaymentLines inner join APPaymentHeaders on apnAPPaymentSessionID=aptAPPaymentSessionID and apnAPPaymentHeaderID=aptAPPaymentHeaderID where aptCreditAPInvoiceID=appAPInvoiceID AND APPaymentHeaders.aptPostedToGL = -1),0) as credpay,  isnull((select sum(apnPaymentAmountForeign) from APPaymentLines inner join APPaymentHeaders on apnAPPaymentSessionID=aptAPPaymentSessionID and apnAPPaymentHeaderID=aptAPPaymentHeaderID where aptCreditAPInvoiceID=appAPInvoiceID AND APPaymentHeaders.aptPostedToGL = -1),0) as credpayForeign,  isnull((select sum(arnPaymentAmount + arnDiscountAmount + arnDiscountTaxAmount + arnSecondDiscountTaxAmount - arnAdjustmentAmount - arnTaxAmount - arnSecondTaxAmount + arnExchangeAmount) from ARPaymentLines inner join ARPaymentHeaders on arnARPaymentSessionID=artARPaymentSessionID and arnARPaymentHeaderID=artARPaymentHeaderID where arnAPInvoiceID=appAPInvoiceID AND ARPaymentHeaders.artPostedToGL = -1),0) as offset,  isnull((select sum(arnPaymentAmountForeign + arnDiscountAmountForeign + arnDiscountTaxAmountForeign + arnSecondDisTaxAmtForeign - arnAdjustmentAmountForeign - arnTaxAmountForeign - arnSecondTaxAmountForeign) from ARPaymentLines inner join ARPaymentHeaders on arnARPaymentSessionID=artARPaymentSessionID and arnARPaymentHeaderID=artARPaymentHeaderID where arnAPInvoiceID=appAPInvoiceID AND ARPaymentHeaders.artPostedToGL = -1),0) as offsetForeign,  isnull((select sum(apvExchangeAmount) from APInvoiceRevaluations where apvAPInvoiceID=appAPInvoiceID),0)  as exchangeAmt from APInvoices where appInvoiceTotalBase <> 0 ) As Test Where Test.appAPInvoiceID = APInvoices.appAPInvoiceID And (Test.appInvoiceTotalBase <> (Test.appInvoiceBalanceBase + Test.invpay - Test.credpay + Test.offset + Test.exchangeAmt)  Or Test.appInvoiceTotalForeign <> (Test.appInvoiceBalanceForeign + Test.invpayForeign - Test.credpayForeign + Test.offsetForeign)) And Test.appInvoiceBalanceBase <> 0 And Test.appInvoiceBalanceForeign <> 0 ");
